import unittest

from solution import validate_mounts


EXPECTED = [
    {"prefix": "/control/", "module": "control.urls"},
    {"prefix": "/", "module": "records.urls"},
    {"prefix": "/session/", "module": "accounts.urls"},
]


class ValidateMountsTests(unittest.TestCase):
    def test_exact_match(self):
        value = [dict(item) for item in EXPECTED]
        self.assertIs(validate_mounts(value), True)
        self.assertEqual(value, EXPECTED)

    def test_all_other_shapes_return_false(self):
        class ListSubclass(list): pass
        class DictSubclass(dict): pass
        cases = [
            None, 1, "x", {}, [], EXPECTED[:2], EXPECTED + [{}],
            tuple(EXPECTED), list(reversed(EXPECTED)),
            [dict(EXPECTED[0], extra=1), EXPECTED[1], EXPECTED[2]],
            [DictSubclass(EXPECTED[0]), EXPECTED[1], EXPECTED[2]],
            ListSubclass(EXPECTED),
            [dict(EXPECTED[0], prefix="/wrong/"), EXPECTED[1], EXPECTED[2]],
        ]
        for value in cases:
            with self.subTest(value=value):
                self.assertIs(validate_mounts(value), False)

    def test_never_raises_for_hostile_values(self):
        class Odd:
            def __iter__(self):
                raise RuntimeError("must not escape")
        self.assertIs(validate_mounts(Odd()), False)


if __name__ == "__main__":
    unittest.main()

